const body = $json.body ?? $json;
const ingredients = Array.isArray(body.ingredients) ? body.ingredients : [];
const prefs = body.preferences ?? {};
if (ingredients.length === 0) { throw new Error('No ingredients provided'); }
if (!prefs.portions || prefs.portions < 1) { throw new Error('Invalid portions'); }
const list = ingredients.map(i => `${i.amount}${i.unit === 'piece' ? ' pc' : i.unit} ${i.name}`).join(', ');
const prompt = [
  'You are a recipe generator. Return ONLY a valid JSON array of exactly 3 recipe objects. No markdown, no commentary.',
  'Each object must have: id (kebab-case string), index (1-3), title, cookingTimeMin (number), cuisine, timeLabel, diet, likes (number 0-100), cooks (number), nutrition {calories,protein,fat,carbs} (all numbers), yourIngredients [{amount,name}], extraIngredients [{amount,name}], steps [{order,title,chef,text}].',
  `Available ingredients: ${list}.`,
  `Preferences: portions=${prefs.portions}, cooks=${prefs.cooks}, time=${prefs.time}, cuisine=${prefs.cuisine}, diet=${prefs.diet}.`,
  `Distribute the steps across ${prefs.cooks} chef(s) using the chef field (values 1..${prefs.cooks}).`
].join('\n');
return [{ json: { prompt } }];

const res = $json;
const text = res?.candidates?.[0]?.content?.parts?.[0]?.text ?? '[]';
let data;
try { data = JSON.parse(text); } catch (e) { throw new Error('Model did not return valid JSON'); }
const recipes = Array.isArray(data) ? data : (data.recipes ?? []);
const normalized = recipes.slice(0, 3).map((r, i) => ({ ...r, index: r.index ?? i + 1 }));
return [{ json: { recipes: normalized } }];
